window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7118312d0f2c87bb"]={"versions": [{"id": "FIG-7118312d0f2c87bb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponenten- und Schnittstellendiagramm (AUTOSAR Adaptive Platform Architecture Modeling).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifiziert im Dokument <code>AUTOSAR_EXP_SWArchitecture</code> (Release R21-11) die Sicherheitsarchitektur der AUTOSAR Adaptive Platform (ARA). Das Diagramm definiert das <em>Policy Enforcement Point (PEP) / Policy Decision Point (PDP)</em>-Muster: Der funktionale Cluster <em>Identity and Access Management</em> (IAM) implementiert den zentralen PDP, welcher von peripheren funktionalen Clustern (als PEPs) zur autoritativen Zugriffskontrolle abgefragt wird.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Schnittstelle (Interface):</strong>\n<ul class=\"fig-list\"><li><code>PolicyDecisionPoint</code> mit Stereotypen <code>«aapInternal,aapNativeInterface»</code>: Plattform-interne native C++-Schnittstelle. Sie ist nicht für reguläre Adaptive Applications (<code>ara::*</code>) bestimmt, sondern für die Inter-Cluster-Kommunikation der Plattform.\n</li><li>Operation: <code>+ CheckAccess()</code> – Zentrale Prüffunktion für Zugriffsrechte.\n</li></ul>\n</li><li><strong>Realisierende Komponente (Provider):</strong>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Identity and Access Management</code>: Realisiert (<code>InterfaceRealization</code>) die Schnittstelle <code>PolicyDecisionPoint</code>.\n</li></ul>\n</li><li><strong>Konsumierende Komponenten (Consumers / PEPs):</strong>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Communication Management</code>: Nutzt <code>PolicyDecisionPoint</code> (<code>«use»</code>) zur Validierung von Service-Offers, Event-Subscriptions und RPC-Methodenaufrufen.\n</li><li><code>«aapFunctionalCluster» Cryptography</code> (Kennzeichnung: <code>daemon-based</code>): Nutzt <code>PolicyDecisionPoint</code> (<code>«use»</code>) zur Autorisierung des Zugriffs auf Schlüssel-Slots, Zertifikate und Krypto-Routinen.\n</li><li><code>«aapFunctionalCluster» Diagnostic Management</code> (Kennzeichnung: <code>daemon-based</code>): Nutzt <code>PolicyDecisionPoint</code> (<code>«use»</code>) zur Absicherung von UDS/DoIP-Diensten, Routinen (RIDs) und Daten-Identifiern (DIDs).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eine Adaptive Application stellt über die öffentliche ARA-API eine Anfrage an einen funktionalen Cluster (z. B. <code>ara::crypto</code> zum Laden eines Schlüssels, <code>ara::com</code> für Service Discovery oder <code>ara::diag</code> zur Ausführung eines Diagnosedienstes).\n</li><li><strong>PEP-Interzeption:</strong> Der jeweilige Cluster agiert als Policy Enforcement Point und fängt die Anforderung ab, bevor Ressourcen allokiert oder Daten verarbeitet werden.\n</li><li><strong>Synchrone Richtlinienprüfung:</strong> Der Cluster ruft intern <code>PolicyDecisionPoint::CheckAccess()</code> des IAM auf und übergibt dabei den Sicherheitskontext (Prozessidentität/UID/App-Token, angeforderte Capability/Operation und Zielobjekt).\n</li><li><strong>Entscheidung &amp; Durchsetzung:</strong> \n<ul class=\"fig-list\"><li><strong>Grant:</strong> IAM verifiziert die Anfrage gegen die hinterlegten Deployment-Policies/Manifeste; der Cluster führt die Operation aus.\n</li><li><strong>Denial:</strong> IAM lehnt die Anfrage ab; der aufrufende Cluster bricht den Vorgang ab und meldet einen Zugriffsfehler (z. B. <code>ara::core::ErrorCode</code> für Security/Access Violation) an die Applikation.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Schnittstellenklassifikation (<code>«aapInternal»</code>):</strong> <code>CheckAccess()</code> ist strikt plattformintern. Stack- und Basis-Software-Entwickler müssen diesen API-Vertrag implementieren bzw. anbinden; Applikations-Entwickler haben keinen direkten Zugriff auf diese Schnittstelle.\n</li><li><strong>Daemon-Konfiguration &amp; IPC-Overhead:</strong> Da <em>Cryptography</em> und <em>Diagnostic Management</em> als <code>daemon-based</code> ausgeführt sind, erfolgt der Aufruf an IAM je nach Implementierungsarchitektur über einen prozessübergreifenden IPC. Plattform-Entwickler müssen hier effiziente IPC-Mechanismen oder lokales PEP-Caching implementieren, um Latenzen bei wiederkehrenden <code>CheckAccess()</code>-Aufrufen zu minimieren.\n</li><li><strong>Manifest- &amp; Rechtevergabe (Applikations-Sicht):</strong> Zugriffsrechte werden nicht prozedural codiert, sondern deklarativ im Execution Manifest / Service Instance Manifest (ARXML) definiert (z. B. über IAM-Grants für spezifische Services, Krypto-Slots oder Diagnosedienste). IAM lädt diese Policies beim Startprozess und hinterlegt sie im PDP.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ef2e9fd025f43d48", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponenten- und Schnittstellendiagramm (AUTOSAR Adaptive Platform Architecture Modeling).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifiziert im Dokument <code>AUTOSAR_EXP_SWArchitecture</code> (Release R21-11) die Sicherheitsarchitektur der AUTOSAR Adaptive Platform (ARA). Das Diagramm definiert das <em>Policy Enforcement Point (PEP) / Policy Decision Point (PDP)</em>-Muster: Der funktionale Cluster <em>Identity and Access Management</em> (IAM) implementiert den zentralen PDP, welcher von peripheren funktionalen Clustern (als PEPs) zur autoritativen Zugriffskontrolle abgefragt wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Schnittstelle (Interface):</strong>\n<ul class=\"fig-list\"><li><code>PolicyDecisionPoint</code> mit Stereotypen <code>«aapInternal,aapNativeInterface»</code>: Plattform-interne native C++-Schnittstelle. Sie ist nicht für reguläre Adaptive Applications (<code>ara::*</code>) bestimmt, sondern für die Inter-Cluster-Kommunikation der Plattform.\n</li><li>Operation: <code>+ CheckAccess()</code> – Zentrale Prüffunktion für Zugriffsrechte.\n</li></ul>\n</li><li><strong>Realisierende Komponente (Provider):</strong>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Identity and Access Management</code>: Realisiert (<code>InterfaceRealization</code>) die Schnittstelle <code>PolicyDecisionPoint</code>.\n</li></ul>\n</li><li><strong>Konsumierende Komponenten (Consumers / PEPs):</strong>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Communication Management</code>: Nutzt <code>PolicyDecisionPoint</code> (<code>«use»</code>) zur Validierung von Service-Offers, Event-Subscriptions und RPC-Methodenaufrufen.\n</li><li><code>«aapFunctionalCluster» Cryptography</code> (Kennzeichnung: <code>daemon-based</code>): Nutzt <code>PolicyDecisionPoint</code> (<code>«use»</code>) zur Autorisierung des Zugriffs auf Schlüssel-Slots, Zertifikate und Krypto-Routinen.\n</li><li><code>«aapFunctionalCluster» Diagnostic Management</code> (Kennzeichnung: <code>daemon-based</code>): Nutzt <code>PolicyDecisionPoint</code> (<code>«use»</code>) zur Absicherung von UDS/DoIP-Diensten, Routinen (RIDs) und Daten-Identifiern (DIDs).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eine Adaptive Application stellt über die öffentliche ARA-API eine Anfrage an einen funktionalen Cluster (z. B. <code>ara::crypto</code> zum Laden eines Schlüssels, <code>ara::com</code> für Service Discovery oder <code>ara::diag</code> zur Ausführung eines Diagnosedienstes).\n</li><li><strong>PEP-Interzeption:</strong> Der jeweilige Cluster agiert als Policy Enforcement Point und fängt die Anforderung ab, bevor Ressourcen allokiert oder Daten verarbeitet werden.\n</li><li><strong>Synchrone Richtlinienprüfung:</strong> Der Cluster ruft intern <code>PolicyDecisionPoint::CheckAccess()</code> des IAM auf und übergibt dabei den Sicherheitskontext (Prozessidentität/UID/App-Token, angeforderte Capability/Operation und Zielobjekt).\n</li><li><strong>Entscheidung &amp; Durchsetzung:</strong> \n<ul class=\"fig-list\"><li><strong>Grant:</strong> IAM verifiziert die Anfrage gegen die hinterlegten Deployment-Policies/Manifeste; der Cluster führt die Operation aus.\n</li><li><strong>Denial:</strong> IAM lehnt die Anfrage ab; der aufrufende Cluster bricht den Vorgang ab und meldet einen Zugriffsfehler (z. B. <code>ara::core::ErrorCode</code> für Security/Access Violation) an die Applikation.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Schnittstellenklassifikation (<code>«aapInternal»</code>):</strong> <code>CheckAccess()</code> ist strikt plattformintern. Stack- und Basis-Software-Entwickler müssen diesen API-Vertrag implementieren bzw. anbinden; Applikations-Entwickler haben keinen direkten Zugriff auf diese Schnittstelle.\n</li><li><strong>Daemon-Konfiguration &amp; IPC-Overhead:</strong> Da <em>Cryptography</em> und <em>Diagnostic Management</em> als <code>daemon-based</code> ausgeführt sind, erfolgt der Aufruf an IAM je nach Implementierungsarchitektur über einen prozessübergreifenden IPC. Plattform-Entwickler müssen hier effiziente IPC-Mechanismen oder lokales PEP-Caching implementieren, um Latenzen bei wiederkehrenden <code>CheckAccess()</code>-Aufrufen zu minimieren.\n</li><li><strong>Manifest- &amp; Rechtevergabe (Applikations-Sicht):</strong> Zugriffsrechte werden nicht prozedural codiert, sondern deklarativ im Execution Manifest / Service Instance Manifest (ARXML) definiert (z. B. über IAM-Grants für spezifische Services, Krypto-Slots oder Diagnosedienste). IAM lädt diese Policies beim Startprozess und hinterlegt sie im PDP.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7118312d0f2c87bb", "to": "FIG-ef2e9fd025f43d48", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
